// 기본 재귀 버전
int64_t fib(int64_t n) {
    if (n <= 1) {
        return n;
    }
    return fib(n - 1) + fib(n - 2);
}

// 반복문 버전 (효율적)
int64_t fib_iterative(int64_t n) {
    if (n <= 1) {
        return n;
    }

    int64_t a = 0, b = 1;
    for (int64_t i = 2; i <= n; i++) {
        int64_t temp = a + b;
        a = b;
        b = temp;
    }
    return b;
}

// 동적 계획법 버전 (메모이제이션 배열 사용)
int64_t fib_dp(int64_t n) {
    if (n <= 1) {
        return n;
    }

    // 배열 크기 제한 (스택 오버플로우 방지)
    if (n > 100) {
        return fib_iterative(n);
    }

    int64_t dp[n + 1];
    dp[0] = 0;
    dp[1] = 1;

    for (int64_t i = 2; i <= n; i++) {
        dp[i] = dp[i - 1] + dp[i - 2];
    }

    return dp[n];
}

